import 'jest';
import { mapAndValidate } from '../../src';

describe('mapAndValidate()', () => {
    test('should throw an error if the source and target do not match types', () => {
        const source = { foo: 1 };
        const target = { foo: '1' };
        expect(() => mapAndValidate(source, target)).toThrow();
    });

    test('should throw an error if the source does not contain a property in the target', () => {
        const source = { foo: 1 };
        const target = { bar: 1 };
        expect(() => mapAndValidate(source, target)).toThrow();
    });

    test('should return undefined if the source and target match', () => {
        const source = { foo: 1 };
        const target = { foo: 1 };
        expect(mapAndValidate(source, target)).toEqual(void 0);
    });
});